void dcn314_hubp_pg_control ( struct dce_hwseq * hws , unsigned int hubp_inst , bool power_on ) { struct dc_context * ctx = hws -> ctx ; union dmub_rb_cmd cmd ; if ( hws -> ctx -> dc -> debug . disable_hubp_power_gate ) { return ; } PERF_TRACE ( ) ; cmd . domain_control . header . type = DMUB_CMD__VBIOS ; cmd . domain_control . header . sub_type = DMUB_CMD__VBIOS_DOMAIN_CONTROL ; cmd . domain_control . header . payload_bytes = sizeof ( cmd . domain_control . data ) ; cmd . domain_control . data . inst = hubp_inst ; cmd . domain_control . data . power_gate = ! power_on ; dc_dmub_srv_cmd_queue ( ctx -> dmub_srv , & cmd ) ; dc_dmub_srv_cmd_execute ( ctx -> dmub_srv ) ; dc_dmub_srv_wait_idle ( ctx -> dmub_srv ) ; PERF_TRACE ( ) ; } 